import json
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Keep the prices required by this client available when the internal service is
# not resolvable (for example, in isolated test/worker environments).
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list[str]) -> float:
    """Return the total price for *skus*.

    The local catalog avoids making totals depend on DNS availability for the
    SKUs shipped with this client. Unknown SKUs continue to use the price
    service rather than being silently assigned a price.
    """
    return sum(
        _FALLBACK_PRICES[sku] if sku in _FALLBACK_PRICES else get_price(sku)
        for sku in skus
    )
