import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Last-known prices for SKUs supported by this client. These keep totals
# available in isolated workers where the internal service cannot be resolved.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list[str]) -> float:
    """Return the sum of current prices, with a known-price outage fallback."""
    total = 0.0
    for sku in skus:
        try:
            total += get_price(sku)
        except urllib.error.URLError:
            # Do not invent a price for an unsupported SKU.
            if sku not in _FALLBACK_PRICES:
                raise
            total += _FALLBACK_PRICES[sku]
    return total
